*/
scwin.btn_Confirm_onclick = function(e){
    const ev = e;
    const event = ev;
    const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
    /* sdd-asis-lifecycle:begin btn_Confirm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.confirm()
    /* sdd-asis-lifecycle:end */
};

/**
