*/
scwin.__ev_2_btn_Confirm_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __ev_2_btn_Confirm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.confirm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40211.__ev_2_btn_Confirm_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_ChkDuplicate_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ChkDuplicate_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ChkDuplicate_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.chkDuplicate()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40211.btn_ChkDuplicate_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40211.btn_Close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ChkDuplicate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ChkDuplicate = async function () {
    const sbmOptions = {
        id: "tx_fn_ChkDuplicate",
        method: "post",
        action: "/outer/popRegister.do?method=searchIdDuplication",
        ref: "dma_ChkDuplicateReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40211.tx_fn_ChkDuplicate" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($c.util.getComponent(scwin.displayDiv) && $c.util.getComponent(scwin.displayDiv).show ? $c.util.getComponent(scwin.displayDiv).show() : console.warn('[sdd] show 대상 미해결: ' + scwin.displayDiv));
    ($c.util.getComponent(scwin.noneDiv) && $c.util.getComponent(scwin.noneDiv).hide ? $c.util.getComponent(scwin.noneDiv).hide() : console.warn('[sdd] hide 대상 미해결: ' + scwin.noneDiv));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.confirm = function () {
    /* sdd-asis-lifecycle:begin fn_Confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_UseUsrId === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_UseUsrId($c.util.getComponent('ipt_usrId').getValue()) : void 0), $c.win.closePopup([$c.util.getComponent('ipt_usrId').getValue()]));
    scwin.close();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_Close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkDuplicate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkDuplicate = async function () {
    /* sdd-asis-lifecycle:begin fn_ChkDuplicate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('idForm');
    const usrIdObj = $c.util.getComponent('ipt_usrId');
    if ($c.cm.fn_NullChk(usrIdObj)) {
        return;
    }
    if (!$c.cm.fn_ChkNoneNum(usrIdObj)) {
        return;
    }
    if (!$c.cm.fn_ChkAlphaNum(usrIdObj, 6, 20)) {
        return;
    }
    $c.util.getComponent("ipt_usrId").setValue((usrIdObj.getValue()).toLowerCase());
    frm.action = '/outer/popRegister.do?method=searchIdDuplication';
    await scwin.tx_fn_ChkDuplicate();
    /* sdd-asis-lifecycle:end */
};
